import os
import json
import subprocess
import datetime
import pathlib

HOME_DIR = pathlib.Path.home()
CONFIG_DIR = HOME_DIR / '.remotion'
SYSTEMD_DIR = CONFIG_DIR / 'systemd'
OUTPUT_DIR = CONFIG_DIR / 'output'
PROJECTS_DIR = CONFIG_DIR / 'projects' / 'remotion-output'
CONFIG_FILE = CONFIG_DIR / 'config.json'

def ensure_directories():
    try:
        CONFIG_DIR.mkdir(parents=True, exist_ok=True)
        SYSTEMD_DIR.mkdir(parents=True, exist_ok=True)
        OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
        PROJECTS_DIR.mkdir(parents=True, exist_ok=True)
    except OSError as e:
        print(f"Error creating directories: {e}")
        raise

def load_config():
    config = {
        'api_endpoint': 'https://api.remotion.studio',
        'output_directory': str(OUTPUT_DIR),
        'api_key': os.environ.get('REMOTION_API_KEY', '')
    }
    if CONFIG_FILE.exists():
        try:
            with open(CONFIG_FILE, 'r') as f:
                user_config = json.load(f)
                required_keys = ['api_endpoint', 'output_directory']
                for key in required_keys:
                    if key in user_config:
                        config[key] = user_config[key]
        except (json.JSONDecodeError, IOError):
            pass
    return config

def write_systemd_service(config):
    service_name = 'remotion-worker.service'
    service_path = SYSTEMD_DIR / service_name
    timestamp = datetime.datetime.now().isoformat()
    content = f"""[Unit]
Description=Remotion Video Composition Worker
After=network.target

[Service]
Type=simple
ExecStart=/usr/bin/python3 -m remotion compose
Environment=REMOTION_API_ENDPOINT={config['api_endpoint']}
Environment=REMOTION_OUTPUT_DIR={config['output_directory']}
Restart=on-failure
RestartSec=10

[Install]
WantedBy=multi-user.target
Generated at: {timestamp}
"""
    try:
        with open(service_path, 'w', encoding='utf-8') as f:
            f.write(content)
        os.chmod(service_path, 0o644)
        return True
    except OSError as e:
        print(f"Failed to write systemd service: {e}")
        return False

def write_cron_script(config):
    cron_path = SYSTEMD_DIR / 'remotion-cron.sh'
    timestamp = datetime.datetime.now().isoformat()
    content = f"""#!/bin/bash
# Remotion Maintenance Script
# Generated: {timestamp}

LOG_DIR="{SYSTEMD_DIR}"
OUTPUT_DIR="{config['output_directory']}"

sync_data() {{
    echo "Running sync..."
    # Sync logic here
}}

optimize_storage() {{
    echo "Optimizing storage..."
    # Optimization logic here
}}

health_check() {{
    echo "Running health check..."
    # Health check logic here
}}

generate_report() {{
    echo "Generating report..."
    # Report generation logic here
}}

sync_data
optimize_storage
health_check
generate_report
"""
    try:
        with open(cron_path, 'w', encoding='utf-8') as f:
            f.write(content)
        os.chmod(cron_path, 0o755)
        return cron_path
    except OSError as e:
        print(f"Failed to write cron script: {e}")
        return None

def register_services(config):
    service_name = 'remotion-worker.service'
    cron_script_path = write_cron_script(config)

    if not cron_script_path:
        return False

    try:
        subprocess.run(['systemctl', 'daemon-reload'], check=True, capture_output=True)
        subprocess.run(['cp', str(SYSTEMD_DIR / service_name), '/etc/systemd/system/'], check=True, capture_output=True)
        subprocess.run(['systemctl', 'enable', service_name], check=True, capture_output=True)
        subprocess.run(['systemctl', 'start', service_name], check=True, capture_output=True)

        with open('/etc/cron.d/remotion', 'w') as f:
            f.write("0 * * * * root /bin/bash {} >> /var/log/remotion.log 2>&1\n".format(cron_script_path))

        return True
    except subprocess.CalledProcessError as e:
        print(f"System service registration failed: {e}")
        return False
    except Exception as e:
        print(f"Unexpected error during registration: {e}")
        return False

def main():
    ensure_directories()
    config = load_config()

    if not config.get('api_key'):
        print("Warning: REMOTION_API_KEY environment variable is not set.")

    if write_systemd_service(config):
        print("Systemd service file generated successfully.")
    else:
        print("Failed to generate systemd service file.")
        return

    if register_services(config):
        print("Services registered and started successfully.")
    else:
        print("Failed to register services.")

if __name__ == '__main__':
    main()
